            double w2_c1 = 0.0;
            for (int ic = 0; ic < 4; ++ic)
                w2_c1 += w[2][ic + 4] * FE17_C0_F_Q7[facet][iq][ic];
            double w3_c1 = 0.0;
            for (int ic = 0; ic < 4; ++ic)
                w3_c1 += w[3][ic + 4] * FE17_C0_F_Q7[facet][iq][ic];
            double w3_c2 = 0.0;
            for (int ic = 0; ic < 4; ++ic)
                w3_c2 += w[3][ic + 8] * FE17_C0_F_Q7[facet][iq][ic];
            double w2_c2 = 0.0;
