class Form_L : public dolfin::Form {
  public:
    // Constructor
    Form_L(std::shared_ptr<const dolfin::FunctionSpace> V0)
        : dolfin::Form(1, 6), f0(*this, 0), s0(*this, 1), X(*this, 2), x_start(*this, 3), pressure(*this, 4),
          T(*this, 5) {
        _function_spaces[0] = V0;

        _ufc_form = std::make_shared<const constituitivelaw_form_1>();
    }

    // Constructor
    Form_L(std::shared_ptr<const dolfin::FunctionSpace> V0, std::shared_ptr<const dolfin::GenericFunction> f0,
           std::shared_ptr<const dolfin::GenericFunction> s0, std::shared_ptr<const dolfin::GenericFunction> X,
           std::shared_ptr<const dolfin::GenericFunction> x_start,
           std::shared_ptr<const dolfin::GenericFunction> pressure, std::shared_ptr<const dolfin::GenericFunction> T)
        : dolfin::Form(1, 6), f0(*this, 0), s0(*this, 1), X(*this, 2), x_start(*this, 3), pressure(*this, 4),
          T(*this, 5) {
        _function_spaces[0] = V0;

        this->f0       = f0;
        this->s0       = s0;
        this->X        = X;
        this->x_start  = x_start;
        this->pressure = pressure;
        this->T        = T;

        _ufc_form = std::make_shared<const constituitivelaw_form_1>();
    }

    // Destructor
    ~Form_L() {}

    /// Return the number of the coefficient with this name
    virtual std::size_t coefficient_number(const std::string& name) const {
        if (name == "f0")
            return 0;
        else if (name == "s0")
            return 1;
        else if (name == "X")
            return 2;
        else if (name == "x_start")
            return 3;
        else if (name == "pressure")
            return 4;
        else if (name == "T")
            return 5;

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return 0;
    }

    /// Return the name of the coefficient with this number
    virtual std::string coefficient_name(std::size_t i) const {
        switch (i) {
        case 0:
            return "f0";
        case 1:
            return "s0";
        case 2:
            return "X";
        case 3:
            return "x_start";
        case 4:
            return "pressure";
        case 5:
            return "T";
        }

        dolfin::dolfin_error("generated code for class Form", "access coefficient data", "Invalid coefficient");
        return "unnamed";
    }

    // Typedefs
    typedef Form_L_FunctionSpace_0          TestSpace;
    typedef Form_L_MultiMeshFunctionSpace_0 MultiMeshTestSpace;
    typedef Form_L_FunctionSpace_1          CoefficientSpace_f0;
    typedef Form_L_FunctionSpace_2          CoefficientSpace_s0;
    typedef Form_L_FunctionSpace_3          CoefficientSpace_X;
    typedef Form_L_FunctionSpace_4          CoefficientSpace_x_start;
    typedef Form_L_FunctionSpace_5          CoefficientSpace_pressure;
    typedef Form_L_FunctionSpace_6          CoefficientSpace_T;

    // Coefficients
    dolfin::CoefficientAssigner f0;
    dolfin::CoefficientAssigner s0;
    dolfin::CoefficientAssigner X;
    dolfin::CoefficientAssigner x_start;
    dolfin::CoefficientAssigner pressure;
    dolfin::CoefficientAssigner T;
};

